"""Final UI composition for compact navigation, progressive ratings and history."""
FEATURE_UI = r"""
<style>
body{padding-bottom:env(safe-area-inset-bottom)!important}.shell{padding-bottom:calc(24px + env(safe-area-inset-bottom))!important;min-width:0}.mobile-bottom-nav{display:none!important}
.topbar{height:auto;min-height:60px;gap:10px;padding-top:max(6px,env(safe-area-inset-top));padding-bottom:6px;flex-wrap:wrap}.topbar nav{display:flex!important;flex:1;justify-content:flex-end;flex-wrap:wrap;gap:2px}.topbar nav button{min-height:44px;padding:8px 10px;font-size:.85rem}.topbar .brand{cursor:pointer}.topbar .brand img{width:120px}.topbar .user{display:none}.header-more{position:relative}.header-more summary{cursor:pointer;min-height:44px;padding:12px 8px;font-size:.85rem}.header-more-items{position:absolute;right:0;top:100%;min-width:150px;display:grid;background:#111620;border:1px solid var(--border);border-radius:10px;padding:6px;z-index:30}
.detail-toolbar{position:sticky;top:0;z-index:115;background:#111620;padding:8px max(12px,env(safe-area-inset-left));padding-top:max(8px,env(safe-area-inset-top));border-bottom:1px solid var(--border)}.detail-toolbar nav{display:flex;gap:8px;margin-bottom:6px}.detail-controls{display:flex;justify-content:space-between;align-items:center}.detail-toolbar .close,.detail-toolbar .mobile-modal-back{position:static!important;display:inline-flex!important;align-items:center;min-height:44px;min-width:44px}.dialog{padding-top:0!important}.detail-body{padding-bottom:calc(24px + env(safe-area-inset-bottom))!important}
.toast{position:static;max-width:100%;padding:10px 14px;margin:0;border-radius:10px;pointer-events:auto}.toast-region{position:relative;z-index:120;display:grid;gap:6px;margin:0 max(12px,env(safe-area-inset-left));pointer-events:none}.toast-region:not(:empty){padding-block:6px}.detail-toolbar .toast-region{margin:0}.toast-dismiss{float:right;margin-left:10px;border:0;background:transparent;color:inherit;min-width:32px;min-height:32px}.release-loading{padding:12px;color:var(--muted)}#auto-request,.best-tv-request{background:var(--surface-2)!important;border:1px solid #74699c!important;min-height:44px;width:100%}.release-actions-bottom{margin-top:14px}.discovery-tools{grid-template-columns:repeat(auto-fit,minmax(120px,1fr))}.rt-score{font-size:.76rem;color:#eebf88}.catalogue-notice{color:var(--warning);font-size:.8rem;margin:10px 0}
.history-wrap{max-width:100%;overflow-x:auto;border:1px solid var(--border);border-radius:12px}.history-table{width:100%;border-collapse:collapse;font-size:.83rem;table-layout:fixed}.history-table th,.history-table td{text-align:left;padding:10px 9px;border-bottom:1px solid var(--border);vertical-align:top;overflow-wrap:anywhere}.history-table th{color:var(--muted);font-weight:750}.history-table th:first-child{width:30%}.history-table th:last-child{width:18%}.history-table .status{display:inline-block;white-space:normal}.history-table button.history-title{border:0;padding:0;background:transparent;color:var(--text);font-weight:750;text-align:left;line-height:1.4;min-height:36px}.history-details td{background:#0d1119;padding:12px}.history-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.history-fields dt{font-size:.72rem;color:var(--muted)}.history-fields dd{margin:3px 0;overflow-wrap:anywhere}.history-paging{display:flex;align-items:center;gap:10px;margin-top:12px}.history-table .processing{color:#c8bdff}.history-table .requested{color:var(--muted)}
@media(max-width:760px){.history-table{font-size:.78rem}.history-table th:first-child{width:35%}.history-table th:last-child{width:26%}.history-table th,.history-table td{padding:8px 6px}.history-table .secondary-column{display:none}.history-fields{grid-template-columns:1fr 1fr}.topbar #users-nav,.topbar #logout,.topbar [data-view="watchlist"]{font-size:.75rem}.topbar .brand img{width:108px}.detail-hero{padding-top:18px}.detail-toolbar nav button{min-height:44px}.detail-toolbar nav{justify-content:space-between}.history-table .status{padding:4px 6px;font-size:.69rem}}
</style>
<script>
(function(){
 const q=id=>document.getElementById(id),modal=q('modal'),dialog=modal.querySelector('.dialog');
 // Keep existing Watchlist, Users and sign-out access in the wrapping header.
 const brand=document.querySelector('.topbar .brand');brand.setAttribute('role','button');brand.tabIndex=0;brand.setAttribute('aria-label','MediaHub Browse');brand.setAttribute('aria-current','page');
 brand.addEventListener('click',()=>showView('browse'));brand.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showView('browse');}});
 document.querySelector('.topbar [data-view="browse"]')?.classList.add('hidden');
 const headerNav=document.querySelector('.topbar nav'),more=document.createElement('details');more.className='header-more';more.innerHTML='<summary>More</summary><div class="header-more-items"></div>';headerNav.append(more);for(const el of [q('users-nav'),q('logout'),headerNav.querySelector('[data-view="watchlist"]')])if(el)more.querySelector('div').append(el);
 more.addEventListener('click',event=>{if(event.target.closest('button'))more.open=false;});
 const toolbar=document.createElement('div');toolbar.className='detail-toolbar';toolbar.innerHTML='<nav aria-label="Detail navigation"><button data-detail-view="browse">Browse</button><button data-detail-view="downloads">Downloads</button><button data-detail-view="setup">Setup</button></nav><div class="detail-controls"></div>';
 dialog.prepend(toolbar);toolbar.querySelector('.detail-controls').append(q('mobile-modal-back'),q('close-modal'));
 toolbar.querySelectorAll('[data-detail-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.detailView)));
 const applyUserBefore=applyUser;applyUser=function(user){applyUserBefore(user);toolbar.querySelector('[data-detail-view="setup"]').classList.toggle('hidden',user.role!=='admin');};if(state.user)applyUser(state.user);
 const showBefore=showView;showView=function(name){cancelDetailWork();const value=showBefore(name);toolbar.querySelectorAll('[data-detail-view]').forEach(b=>b.classList.toggle('active',b.dataset.detailView===name));brand.setAttribute('aria-current',name==='browse'?'page':'false');return value;};
 q('toast').remove();const region=document.createElement('div');region.className='toast-region';region.setAttribute('aria-live','polite');document.body.append(region);
 function placeNotifications(){if(!modal.classList.contains('hidden')){if(region.parentElement!==toolbar)toolbar.append(region);}else if(region.previousElementSibling!==document.querySelector('.topbar'))document.querySelector('.topbar').after(region);}
 window.addEventListener('resize',placeNotifications);new MutationObserver(placeNotifications).observe(modal,{attributes:true,attributeFilter:['class']});
 toast=function(message,kind='info'){placeNotifications();if([...region.children].some(el=>el.dataset.message===message))return;const el=document.createElement('div');el.className='toast';el.dataset.message=message;el.setAttribute('role',kind==='error'?'alert':'status');const dismiss=document.createElement('button');dismiss.className='toast-dismiss';dismiss.textContent='×';dismiss.setAttribute('aria-label','Dismiss notification');dismiss.onclick=()=>el.remove();el.append(dismiss,document.createTextNode(message));region.append(el);while(region.children.length>3)region.firstElementChild.remove();setTimeout(()=>el.remove(),kind==='error'?15000:6500);};
 let generation=0,detailController=null,tvSearch=null,submitting=false,browseScroll=0;
 function cancelDetailWork(){window.MEDIAHUB_PARENT_DETAIL_RESTORE=null;generation++;detailController?.abort();detailController=null;tvSearch?.cancel();tvSearch=null;cancelReleaseSearch();}
 const closeBefore=closeModal;closeModal=function(){cancelDetailWork();const result=closeBefore();requestAnimationFrame(()=>window.scrollTo({top:browseScroll,behavior:'instant'}));return result;};
 q('close-modal').addEventListener('click',event=>{event.stopImmediatePropagation();closeModal();},true);
 window.addEventListener('pagehide',cancelDetailWork);
 async function openTitle(kind,id,trigger){cancelDetailWork();const gen=generation,controller=new AbortController();detailController=controller;browseScroll=window.scrollY;detailTrigger=trigger||document.activeElement;modal.classList.remove('hidden');document.body.classList.add('modal-open');q('detail').innerHTML='<div class="release-loading" role="status">Loading details...</div>';dialog.scrollTop=0;let timer;try{const abort=new Promise((_,reject)=>{controller.signal.addEventListener('abort',()=>reject(new DOMException('Cancelled','AbortError')),{once:true});});timer=setTimeout(()=>controller.abort(),15000);const movie=await Promise.race([api(`catalog/${kind==='tv'?'tv':'movies'}/${id}`,{signal:controller.signal}),abort]);if(gen!==generation||modal.classList.contains('hidden'))return;state.movie=movie;if(kind==='tv')renderTvDetail(movie);else renderDetail();q('close-modal').focus();}catch(error){if(gen===generation&&!modal.classList.contains('hidden')){q('detail').innerHTML=`<div class="empty">${esc(error.name==='AbortError'?'Details request timed out. Close and try again.':error.message)}</div>`;}}finally{clearTimeout(timer);if(detailController===controller)detailController=null;}}
 openMovie=(id,trigger)=>openTitle('movie',id,trigger);openTv=(id,trigger)=>openTitle('tv',id,trigger);
 function addRating(movie){const copy=q('detail').querySelector('.detail-copy')||q('detail').querySelector('.detail-body');if(!copy)return;const rating=document.createElement('div');rating.className='rt-score';rating.textContent='Rotten Tomatoes: N/A';copy.append(rating);const gen=generation;api('critic-ratings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({media_type:movie.media_type==='tv'?'tv':'movie',ids:[movie.tmdb_id]})}).then(data=>{if(gen===generation&&rating.isConnected){const score=data.scores?.[String(movie.tmdb_id)];rating.textContent=`Rotten Tomatoes: ${score==null?'N/A':score+'%'} (critics, via OMDb)`;}}).catch(()=>{});}
 const renderBefore=renderDetail;renderDetail=function(){renderBefore();const movie=state.movie;const year=Number(movie.year||movie.release_date?.slice(0,4));const library=movie.library||{};const knownAvailable=movie.plex?.available||library.plex?.available||library.radarr?.available||library.status==='available';const lifecycle=movie.lifecycle||{};if((year&&year<2024)||knownAvailable||!lifecycle.digital_date&&!lifecycle.theatrical_date||lifecycle.state==='released_unknown')q('detail').querySelector('.lifecycle-card')?.remove();q('detail').querySelectorAll('.release-date-line').forEach(el=>{if(/not announced|uncertain/i.test(el.textContent))el.remove();});q('choose-release')?.remove();q('search-anyway')?.remove();const button=q('auto-request');if(button){button.classList.remove('primary');const actions=document.createElement('div');actions.className='release-actions-bottom';q('release-area').after(actions);actions.append(button);}if(movie.context!=='downloads'){if(!button){const actions=document.createElement('div');actions.className='release-actions-bottom';actions.innerHTML='<button class="button" id="auto-request">Request best release</button>';q('release-area').after(actions);q('auto-request').onclick=e=>submitRequest(null,e.currentTarget);}findReleases(false,true);}addRating(movie);};
 // Keep the proven movie cancellation/deadline implementation. Automatic searches
 // stay at the top, manual refresh retains the release-area scroll behaviour.
 const findBefore=findReleases;findReleases=async function(manualOverride=false,automatic=false){if(movieReleaseSearch&&releaseSearchCurrent(movieReleaseSearch))return;const old=window.MEDIAHUB_AUTOMATIC_DISCOVERY;window.MEDIAHUB_AUTOMATIC_DISCOVERY=automatic;try{return findBefore(manualOverride);}finally{window.MEDIAHUB_AUTOMATIC_DISCOVERY=old;}};
 window.MEDIAHUB_FIND_MOVIE_RELEASES=findReleases;
 submitRequest=async function(token,button){if(submitting)return;submitting=true;const movie=state.movie,gen=generation,original=button.textContent;button.disabled=true;button.textContent='Sending request...';try{const result=await timedApi(`movies/${movie.tmdb_id}/request`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...rules(),release_token:token})});toast(`${movie.title}: ${result.status==='available'?'already available in the library':'request accepted. Check Downloads for progress.'}`,'success');if(gen===generation){closeModal();showView('downloads');}}catch(error){toast(error.message,'error');}finally{submitting=false;if(button.isConnected){button.disabled=false;button.textContent=original;}}};
 const tvRenderBefore=renderTvDetail;renderTvDetail=function(show){tvRenderBefore(show);q('request-tv-series')?.classList.remove('primary');addRating(show);if(show.context==='downloads')return;const body=q('detail').querySelector('.detail-body');body.insertAdjacentHTML('beforeend','<div class="section-title">Available releases</div><label class="field">Season<select id="auto-tv-season"></select></label><div id="auto-tv-releases"></div>');const select=q('auto-tv-season');const seasons=(show.seasons||[]).filter(s=>s.season_number>0);select.innerHTML=seasons.map(s=>`<option value="${s.season_number}">${esc(s.name||'Season '+s.season_number)}</option>`).join('');const aired=seasons.filter(s=>!s.air_date||s.air_date<=new Date().toISOString().slice(0,10));if(aired.length)select.value=String(aired.at(-1).season_number);const search=()=>tvDiscovery(`catalog/tv/${show.tmdb_id}/seasons/${select.value}/releases`,q('auto-tv-releases'));select.onchange=search;if(seasons.length)search();else q('auto-tv-releases').innerHTML='<div class="release-loading">No seasons are announced yet.</div>';};
 async function tvDiscovery(path,area,force=false){if(!area)return;if(tvSearch?.path===path&&tvSearch.area===area&&!force)return;tvSearch?.cancel();const controller=new AbortController(),gen=generation;let rejectAbort,timer;const job={path,area,cancel(){controller.abort();rejectAbort?.(new DOMException('Cancelled','AbortError'));}};tvSearch=job;area.setAttribute('aria-busy','true');area.innerHTML='<div class="release-loading" role="status">Finding TV releases...</div>';try{const abort=new Promise((_,reject)=>{rejectAbort=reject;});timer=setTimeout(()=>job.cancel(),22000);const data=await Promise.race([api(path+(force?'?refresh=true':''),{signal:controller.signal}),abort]);if(tvSearch!==job||gen!==generation||!area.isConnected)return;const eligible=(data.releases||[]).filter(r=>r.eligible),excluded=(data.releases||[]).filter(r=>!r.eligible);area.innerHTML=`<button class="button" data-tv-refresh>Refresh releases</button><div class="releases">${releaseRows({...data,releases:eligible})}</div>${excluded.length?`<details><summary>Unavailable releases (${excluded.length})</summary>${releaseRows({...data,releases:excluded})}</details>`:''}<div class="release-actions-bottom"><button class="button best-tv-request" ${eligible.length?'':'disabled'}>Request best release</button></div>`;area.querySelector('.release h4')?.insertAdjacentHTML('beforebegin',eligible.length?'<span class="best-badge">BEST MATCH</span>':'');area.querySelector('[data-tv-refresh]').onclick=()=>tvDiscovery(path,area,true);area.querySelector('.best-tv-request').onclick=e=>grabTvRelease(eligible[0].release_token,e.currentTarget);bindTvReleaseButtons();}catch(error){if(tvSearch===job&&gen===generation&&area.isConnected){area.innerHTML=`<div class="release-loading">${esc(error.name==='AbortError'?'TV release search timed out.':error.message)}</div><button class="button" data-tv-retry>Retry search</button>`;area.querySelector('[data-tv-retry]').onclick=()=>tvDiscovery(path,area,true);}}finally{clearTimeout(timer);if(tvSearch===job){area.setAttribute('aria-busy','false');tvSearch=null;}}}
 findSeasonPacks=season=>tvDiscovery(`catalog/tv/${season.tmdb_id}/seasons/${season.season_number}/releases`,q('season-content'));findEpisodeReleases=(season,number)=>tvDiscovery(`catalog/tv/${season.tmdb_id}/seasons/${season.season_number}/episodes/${number}/releases`,q('season-content'));
 openSeason=async function(show,number){cancelDetailWork();const gen=generation;try{const season=await timedApi(`catalog/tv/${show.tmdb_id}/seasons/${number}`,{},15000,'Season details timed out. Retry or close this page.');if(gen!==generation||modal.classList.contains('hidden'))return;tvSeasonContext={show,season};renderSeason(season);window.MEDIAHUB_PARENT_DETAIL_RESTORE=()=>{cancelDetailWork();state.movie=show;renderTvDetail(show);};}catch(error){if(gen===generation)toast(error.message,'error');}};
 const renderSeasonBefore=renderSeason;renderSeason=function(season){renderSeasonBefore(season);q('find-season-packs').textContent='Refresh releases';const old=q('back-to-tv'),back=old.cloneNode(true);old.replaceWith(back);back.onclick=()=>{cancelDetailWork();renderTvDetail(tvSeasonContext.show);};findSeasonPacks(season);};
 grabTvRelease=async function(token,button){if(submitting)return;submitting=true;const gen=generation,original=button.textContent;button.disabled=true;button.textContent='Sending to Sonarr...';try{await timedApi('tv/releases/grab',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({release_token:token})});toast('TV release sent to Sonarr. Check Downloads for progress.','success');if(gen===generation){closeModal();showView('downloads');}}catch(error){toast(error.message,'error');}finally{submitting=false;if(button.isConnected){button.disabled=false;button.textContent=original;}}};
 submitTvRequest=async function(id,scope,seasons){if(submitting)return;submitting=true;const gen=generation;try{await timedApi(`tv/${id}/request`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope,seasons})});toast('TV request sent to Sonarr. Check Downloads for progress.');if(gen===generation){closeModal();showView('downloads');}}catch(error){toast(error.message,'error');}finally{submitting=false;}};
 async function timedApi(path,options,timeout=22000,message='Request timed out. Check Downloads before trying again.'){const controller=new AbortController();let rejectAbort;const abort=new Promise((_,reject)=>{rejectAbort=reject;});const deadline=setTimeout(()=>{controller.abort();rejectAbort(new Error(message));},timeout);try{return await Promise.race([api(path,{...options,signal:controller.signal}),abort]);}finally{clearTimeout(deadline);}}

 // Paginated history replaces the effective card renderer without changing legacy
 // API consumers. Expanded rows retain every field on narrow screens.
 let historyPage=1,historyItems=[],expanded=new Set();
 const date=value=>{if(!value)return 'Unknown';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'Unknown':parsed.toLocaleString(undefined,{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});};
 const size=item=>item.size_bytes?`${item.size_is_estimate?'~':''}${(item.size_bytes/(item.size_bytes>=1024**3?1024**3:1024**2)).toFixed(1)} ${item.size_bytes>=1024**3?'GB':'MB'}`:'Unknown';
 function historyDetails(item){const fields=[['Full title',item.display_title],['Requested by',item.requested_by_name],['Type',item.media_type==='tv'?'TV Show':'Movie'],['Size',size(item)+(item.size_is_estimate?' (estimated release size)':'')],['Requested',date(item.created_at)],['Download started',date(item.download_started_at)],['Transfer completed',date(item.download_completed_at)],['Imported',date(item.imported_at)],['Status',item.status_message||item.display_status],['Selected release',item.selected_release_title],['Source',item.selected_release_source],['Error',item.status==='failed'?item.rejection_reason||item.status_message:null]];return `<dl class="history-fields">${fields.filter(([,v])=>v!=null&&v!=='').map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;}
 function renderHistory(data){historyItems=data.items;const container=q('downloads');container.innerHTML=`${data.warning?`<div class="catalogue-notice" role="status">${esc(data.warning)}</div>`:''}<div class="history-wrap"><table class="history-table"><thead><tr><th scope="col">Title</th><th scope="col">Requested by</th><th scope="col">Date & time</th><th scope="col" class="secondary-column">Type</th><th scope="col" class="secondary-column">Size</th><th scope="col">Status</th></tr></thead><tbody>${data.items.map(item=>`<tr data-history-id="${item.id}"><td><button class="history-title" aria-expanded="${expanded.has(item.id)}" aria-controls="history-details-${item.id}">${esc(item.display_title)}</button></td><td>${esc(item.requested_by_name||'Unknown')}</td><td>${esc(date(item.display_timestamp))}</td><td class="secondary-column">${item.media_type==='tv'?'TV Show':'Movie'}</td><td class="secondary-column">${esc(size(item))}</td><td><span class="status ${esc(item.status)}">${esc(item.display_status)}${item.display_progress==null?'':` ${Number(item.display_progress).toFixed(0)}%`}</span></td></tr><tr id="history-details-${item.id}" class="history-details ${expanded.has(item.id)?'':'hidden'}"><td colspan="6">${historyDetails(item)}</td></tr>`).join('')||'<tr><td colspan="6">No MediaHub requests yet.</td></tr>'}</tbody></table></div><div class="history-paging"><button class="button" id="history-prev" ${data.page<=1?'disabled':''}>Previous</button><span>${data.total} requests · Page ${data.page} of ${data.total_pages}</span><button class="button" id="history-next" ${data.page>=data.total_pages?'disabled':''}>Next</button></div>`;container.querySelectorAll('[data-history-id]').forEach(row=>row.addEventListener('click',()=>{const id=Number(row.dataset.historyId);expanded.has(id)?expanded.delete(id):expanded.add(id);q(`history-details-${id}`).classList.toggle('hidden',!expanded.has(id));row.querySelector('button').setAttribute('aria-expanded',String(expanded.has(id)));}));q('history-prev').onclick=()=>{historyPage--;loadDownloads();};q('history-next').onclick=()=>{historyPage++;loadDownloads();};}
 loadDownloads=async function(silent=false){if(state.downloadLoading)return;state.downloadLoading=true;try{const data=await api(`download-history?page=${historyPage}`);if(state.view==='downloads')renderHistory(data);}catch(error){toast(error.message,'error');if(!historyItems.length)q('downloads').innerHTML='<div class="empty">Could not load history. Use Refresh to retry.</div>';}finally{state.downloadLoading=false;}};
 // Provider controls use the existing secure server settings persistence.
 document.querySelector('#setup-view .setup-grid').insertAdjacentHTML('beforeend','<article class="service"><div class="service-head">Rotten Tomatoes via OMDb <span id="omdb-status" class="badge">Optional</span></div><div class="fields"><label class="field">OMDb API key<input type="password" autocomplete="new-password" id="omdb_api_key"></label><div class="hint">Optional free key from <a href="https://www.omdbapi.com/apikey.aspx" target="_blank" rel="noopener">OMDb</a>. Critic ratings are not supplied by TMDB. Availability varies, especially for TV. MediaHub budgets 400 requests/day; the free provider limit is 1,000/day. Non-commercial use, CC BY-NC 4.0.</div><button class="button" id="save-omdb">Save OMDb key</button><button class="button" id="test-omdb">Test connection</button></div></article>');
 async function omdbStatus(){try{const data=await api('setup/omdb');q('omdb-status').textContent=data.configured?'Configured':'Optional';q('omdb_api_key').placeholder=data.configured?'Saved, enter a new key to replace':'';}catch(_){}}
 q('save-omdb').onclick=async()=>{try{await api('setup/integrations',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({updates:{omdb_api_key:q('omdb_api_key').value}})});q('omdb_api_key').value='';await omdbStatus();toast('OMDb key saved.');}catch(error){toast(error.message,'error');}};
 q('test-omdb').onclick=async e=>{e.target.disabled=true;try{const result=await api('setup/omdb/test',{method:'POST'});q('omdb-status').textContent=result.status;toast(result.message,result.status==='error'?'error':'info');}catch(error){toast(error.message,'error');}finally{e.target.disabled=false;}};
 const setupBefore=loadSetup;loadSetup=async function(){await Promise.all([setupBefore(),omdbStatus()]);};
 // Progressive card ratings are one bounded batch per catalogue render, never
 // per-card mutation observers. Late responses may only update their own cards.
 const appendBefore=appendUnique;appendUnique=function(items,cardFn,idFn,reset=false){appendBefore(items,cardFn,idFn,reset);const kind=browseMedia;const cards=items.map(item=>({item,card:q('movies').querySelector(`[${kind==='tv'?'data-tv-id':'data-id'}="${item.tmdb_id}"]`)})).filter(x=>x.card);if(!cards.length)return;for(const {item,card} of cards){let node=card.querySelector('.rt-score');if(!node){node=document.createElement('div');node.className='rt-score';card.append(node);}if(item.rt_score!=null)node.textContent=`RT critics ${item.rt_score}%`;}
 if(items.some(i=>i.rt_score==null))api('critic-ratings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({media_type:kind,ids:items.slice(0,20).map(i=>i.tmdb_id)})}).then(data=>{for(const {item,card} of cards){const score=data.scores?.[String(item.tmdb_id)];if(card.isConnected&&score!=null)card.querySelector('.rt-score').textContent=`RT critics ${score}%`;}}).catch(()=>{});};
})();
</script>
"""
